"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { FieldGroup, FieldLegend, FieldSet } from "@/components/ui/field"
import { Progress, ProgressLabel, ProgressValue } from "@/components/ui/progress"

type WizardStep = { id: string; title: string; content: React.ReactNode }

/**
 * Multi-step form (after diceui stepper): aria-nova Field set per step, a
 * Progress bar for position, Back / Next buttons and a final review region.
 */
export default function Wizard({
  steps,
  review,
  onSubmit,
  submitLabel = "Submit",
}: {
  steps: WizardStep[]
  review?: React.ReactNode
  onSubmit?: () => void
  submitLabel?: string
}) {
  const total = steps.length + (review ? 1 : 0)
  const [index, setIndex] = React.useState(0)
  const onReview = review !== undefined && index === steps.length
  const step = steps[index]
  const last = index === total - 1

  return (
    <section data-slot="wizard" className="py-8">
      <div className="mx-auto flex max-w-xl flex-col gap-6 px-6">
        <Progress value={((index + 1) / total) * 100} aria-label="Progress">
          <ProgressLabel>
            Step {index + 1} of {total}
          </ProgressLabel>
          <ProgressValue />
        </Progress>
        <form
          onSubmit={(e) => {
            e.preventDefault()
            if (last) onSubmit?.()
            else setIndex((i) => i + 1)
          }}
          className="flex flex-col gap-6"
        >
          {onReview ? (
            <div role="region" aria-label="Review">{review}</div>
          ) : (
            <FieldSet>
              <FieldLegend>{step?.title}</FieldLegend>
              <FieldGroup>{step?.content}</FieldGroup>
            </FieldSet>
          )}
          <div className="flex justify-between gap-2">
            <Button variant="outline" isDisabled={index === 0} onPress={() => setIndex((i) => Math.max(0, i - 1))}>
              Back
            </Button>
            <Button type="submit">{last ? submitLabel : "Next"}</Button>
          </div>
        </form>
      </div>
    </section>
  )
}
